css:
:root {
  --bg-base: #0a0a0a;
  --bg-surface: #111111;
  --bg-card: #1f1f1f;
  --border: #2a2a2a;
  --text: #fafafa;
  --text-muted: #a1a1aa;
  --accent: #0ea5e9;
  --success: #22c55e;
  --danger: #ef4444;
  --warning: #f59e0b;

  /* Uma cor por fonte de receita — a mesma em pílula, gráfico e avatar. */
  --src-empresa: #0ea5e9;
  --src-impressionart: #8b5cf6;
  --src-moto: #f59e0b;
  --src-mos: #22c55e;
  --src-nata: #ec4899;

  --fonte: 'Manrope', sans-serif;
  --fonte-titulo: 'Sora', sans-serif;
  --fonte-mono: 'JetBrains Mono', monospace;
}

body { background: var(--bg-base); color: var(--text); font-family: var(--fonte); }

/* Número em tabela, card ou badge nunca "dança" ao atualizar. */
.bs-num { font-variant-numeric: tabular-nums; }

.bs-valor {
  width: min(420px, 100%);
  padding: 20px; border: 1px solid var(--border); border-radius: 10px; background: var(--bg-base);
}

.bs-valor-rotulo {
  margin-bottom: 8px;
  font-size: 11px; text-transform: uppercase; letter-spacing: 0.06em; color: var(--text-muted);
}

.bs-valor-linha { display: flex; align-items: baseline; gap: 8px; }
/* Fora do input pra nunca ser apagado junto com o número. */
.bs-valor-moeda { font-size: 22px; font-weight: 500; color: var(--text-muted); }

.bs-valor-input {
  width: 100%; border: none; outline: none; background: transparent;
  font-family: var(--fonte-titulo); font-size: 44px; font-weight: 600;
  letter-spacing: -0.03em; color: var(--text);
}
.bs-valor-entrada .bs-valor-input { color: var(--success); }
.bs-valor-saida .bs-valor-input { color: var(--danger); }

.bs-valor-ajuda { margin-top: 8px; font-size: 12px; color: var(--text-muted); }

