// Centavos como inteiro, sempre. Float em dinheiro vira diferença de um
// centavo na conciliação, e ninguém acha de onde veio.
function formatar(centavos) {
  return (centavos / 100).toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 })
}

export function iniciarCampoValor(raiz, aoMudar) {
  const input = raiz.querySelector('.bs-valor-input')

  input.addEventListener('input', () => {
    // Reconstrói do inteiro a cada tecla: o cursor fica no fim e o backspace
    // apaga da direita, como numa maquininha.
    const digitos = input.value.replace(/\D/g, '')
    const centavos = digitos === '' ? 0 : parseInt(digitos, 10)
    raiz.dataset.centavos = String(centavos)
    input.value = formatar(centavos)
    aoMudar?.(centavos)
  })
}
